HTML = "<!doctype html><html lang=\"ko\"><head><meta charset=\"utf-8\"><meta name=\"viewport\" content=\"width=device-width,initial-scale=1\"><title>GEXOption · 소라 AI</title><style>\n:root{color-scheme:dark;font-family:system-ui,sans-serif;background:#0b1422;color:#edf4ff}*{box-sizing:border-box}body{margin:0}header{padding:10px 14px;border-bottom:1px solid #34445c;display:flex;align-items:center;justify-content:space-between}h1{font-size:19px;margin:0}.tiny{color:#a9bcd6;font-size:12px}.shell{max-width:1200px;margin:auto}.layout{display:grid;grid-template-columns:260px minmax(0,1fr);gap:12px;padding:12px}.sidebar,.workspace{border:1px solid #34445c;border-radius:12px;background:#132139}.sidebar{padding:12px;max-height:85dvh;overflow:auto}.sidebar button{width:100%;margin:3px 0;text-align:left}.workspace{display:flex;flex-direction:column;height:calc(100dvh - 80px);min-height:560px;overflow:hidden}.toolbar{display:flex;gap:8px;align-items:center;padding:9px;border-bottom:1px solid #34445c}select,button,input{font:inherit;color:#ecf3ff;background:#263952;border:1px solid #49627f;border-radius:9px;padding:10px}button{cursor:pointer}button:disabled{opacity:.5}.toolbar select{max-width:60%;min-width:0}.chart{flex:1;min-height:0;padding:10px;display:flex;flex-direction:column;gap:8px;border-bottom:1px solid #34445c}.plot{flex:1;min-height:70px;width:100%;border:1px solid #30425c;border-radius:9px;background:#0d1b2c}svg{width:100%;height:100%}.chat{flex:2;min-height:0;display:flex;flex-direction:column}.messages{flex:1;overflow:auto;padding:12px;display:flex;flex-direction:column;gap:10px}.bubble{max-width:89%;padding:10px 12px;border-radius:12px;background:#293a52;white-space:pre-wrap;line-height:1.5;font-size:14px}.bubble.user{align-self:flex-end;background:#166452}.entry{display:flex;gap:7px;padding:9px;border-top:1px solid #34445c}.entry input{flex:1;min-width:0}.muted{color:#afc0d6}.warning{color:#ffd590}.hidden{display:none}.flag{font-size:12px;background:#283c56;padding:5px 8px;border-radius:10px}.search{width:100%;margin-bottom:8px}@media(max-width:680px){header{padding:8px 12px}.layout{display:block;padding:0}.sidebar{display:none}.workspace{height:calc(100dvh - 51px);min-height:0;border-radius:0;border:0}.chart{flex:1}.chat{flex:2}.toolbar{padding:6px}.chart{padding:7px}.bubble{font-size:14px}}\n\n.tv-wrap{flex:1;min-height:160px;width:100%;background:#FFFFFF;overflow:hidden;border-radius:9px}.tv-wrap .tradingview-widget-container,.tv-wrap .tradingview-widget-container__widget{height:100%;width:100%}.tv-credit{font-size:11px;color:#a9bcd6}.tv-credit a{color:#83d6c5;text-decoration:underline}\n\n/* SORA light classroom palette: preserve markup and mobile layout. */\n:root{color-scheme:light!important;background:#FFFFFF!important;color:#182638!important}\nbody{background:#FFFFFF!important;color:#182638!important}\nheader,.sidebar,.workspace,.toolbar,.chart,.chat,.messages,.entry{background:#FFFFFF!important;color:#182638!important;border-color:#E1E7EE!important}\n.sidebar,.workspace{box-shadow:none!important}\nselect,button,input{background:#FFFFFF!important;color:#182638!important;border-color:#C9D4E0!important}\nbutton:hover{background:#EEF6F4!important}\n.bubble{background:#F0F4F8!important;color:#182638!important}\n.bubble.user{background:#DBF5ED!important;color:#123B32!important}\n.tiny,.muted,.tv-credit{color:#516277!important}\n.flag{background:#EAF4F1!important;color:#216654!important}\n.plot,.tv-wrap{background:#FFFFFF!important;border-color:#DCE5ED!important}\n.tv-credit a{color:#086E67!important}\n\n/* Gentle grade-tinted LEADER 40 stock list, white classroom theme. */\n#stockList button{border:1px solid #E5EAF1!important;border-radius:9px;margin:4px 0!important;padding:10px 12px!important;background:#F7F9FC!important;color:#243449!important;transition:background .15s,border-color .15s;}\n#stockList button:nth-child(4n + 1){background:#F0F7FF!important;border-color:#DCE9FA!important}\n#stockList button:nth-child(4n + 2){background:#F0FAF7!important;border-color:#D9F0E8!important}\n#stockList button:nth-child(4n + 3){background:#F7F4FF!important;border-color:#E7DFF8!important}\n#stockList button:nth-child(4n){background:#FFF9EF!important;border-color:#F4EADB!important}\n#stockList button:hover,#stockList button:focus-visible{background:#DFEEFF!important;border-color:#87B8E7!important}\n#stockList button[aria-pressed=\"true\"]{background:#DCEFEA!important;border:2px solid #22A987!important;color:#0D594A!important;font-weight:700}\n\n/* Price-direction colors, only after confirmed two-session close data. */\n#stockList button[data-trend=\"up\"]{background:#E7F6EE!important;border-color:#B8E2C9!important;color:#185E3B!important}\n#stockList button[data-trend=\"down\"]{background:#FDEBEC!important;border-color:#F3C5CA!important;color:#94363F!important}\n#stockList button[data-trend=\"flat\"]{background:#F3F5F7!important;border-color:#DDE3E9!important;color:#435367!important}\n#stockList button[data-trend=\"unknown\"]{background:#FFFFFF!important;border-color:#DDE3E9!important;color:#435367!important}\n#stockList button[aria-pressed=\"true\"]{outline:2px solid #22A987!important;outline-offset:-2px;font-weight:700}\n#stockList .daily-move{display:block;font-size:11px;margin-top:2px;opacity:.85}\n\n/* Enlarged TradingView teaching chart: compact controls and readable candles. */\n.workspace .toolbar{padding:6px 10px!important;min-height:44px;gap:8px;border-bottom:0!important}\n.workspace .toolbar select{padding:5px 9px!important;font-size:12px!important;max-width:180px}\n.workspace .chart{flex:1.28!important;min-height:252px!important;padding:4px 10px 8px!important;gap:4px!important}\n.workspace .tv-wrap{min-height:208px!important;border:1px solid #E1E7EE!important}\n.workspace .chat{flex:1!important;min-height:180px}\n.workspace .chart .tiny{font-size:10px!important}\n@media(max-width:680px){.workspace .chart{min-height:224px!important;flex:1!important}.workspace .tv-wrap{min-height:176px!important}.workspace .toolbar{padding:5px 7px!important}.workspace .chat{flex:1!important}}\n.scanbox{border:1px solid #dbe5ed;border-radius:10px;padding:9px;margin-bottom:12px;background:#f8fbff}.scanbox summary{cursor:pointer;font-weight:700;font-size:12px;list-style:revert;padding:3px 0}.scanbox summary:focus-visible{outline:2px solid #22a987;border-radius:4px}.scanbox:not([open]){padding:8px 10px}.scanbuttons{display:grid;grid-template-columns:1fr 1fr;gap:4px;margin:7px 0}.sidebar .scanbuttons button{font-size:11px;padding:8px 5px;text-align:center;margin:0}.scanbox #scanResults button{font-size:12px;padding:7px;text-align:left;background:#edf9f3}.scanbox #scanResults{max-height:190px;overflow:auto}.scanbox .tiny{line-height:1.5}@media(max-width:680px){.layout .sidebar{display:block!important;max-height:270px!important;border-radius:0;padding:9px}.sidebar #stockList{display:none}.scanbox #scanResults{max-height:110px}.scanbuttons{grid-template-columns:repeat(2,minmax(0,1fr))}.workspace{height:calc(100dvh - 335px)!important;min-height:360px!important}}.sora-motto{margin:8px 12px 0;padding:16px 18px;text-align:center;font-size:clamp(19px,2.5vw,31px);font-weight:850;line-height:1.4;letter-spacing:-.045em;color:#123d34;border-radius:12px;background:#eaf7f0;border:1px solid #b9dfcc}.sora-motto span{display:inline}.sora-motto-en{font-size:clamp(14px,1.5vw,19px);font-weight:700;letter-spacing:0;line-height:1.5;color:#276554;margin-top:8px}@media(max-width:680px){.sora-motto{margin:7px 9px;padding:12px;font-size:19px;line-height:1.45}}.index-caption{font-weight:700;font-size:12px;color:#41556a;white-space:nowrap}.index-links{display:flex;gap:5px;margin-left:auto;align-items:center;flex-shrink:0}.index-links button{display:inline-flex;align-items:center;padding:6px 8px;border:1px solid #c9d4e0;border-radius:7px;font-size:12px;font-weight:800;color:#16594e;text-decoration:none;background:#f1faf6}.index-links button:hover,.index-links button:focus-visible{background:#d8eee6;border-color:#62ac94}@media(max-width:900px){.workspace .toolbar{flex-wrap:wrap}.index-links{margin-left:auto}}@media(max-width:680px){.index-links button{font-size:11px;padding:5px 7px}}</style></head><body><div class=\"shell\"><header><h1>GEXOption · 소라 AI</h1><span class=\"flag\">LEADER 40 · 교육용 베타</span></header><div class=\"sora-motto\"><div class=\"sora-motto-ko\">시장을 먼저 보고, 주도주를 선택하고,<span> 패턴을 기다린 뒤, 확인된 수급에 따라 대응한다.</span></div><div class=\"sora-motto-en\" lang=\"en\">Read the Market. Choose the Leaders. Wait for the Setup. Act on Confirmed Order Flow.</div></div><div class=\"layout\"><aside class=\"sidebar\"><strong>LEADER 40</strong><p class=\"tiny\">초기 후보 · 등급 검증 전</p><details class=\"scanbox\"><summary>일봉 스윙 스캐너 · 지연 데이터</summary><div class=\"scanbuttons\"><button type=\"button\" data-scan=\"pullback\">① SMA21 눌림</button><button type=\"button\" data-scan=\"hull\">② Hull21 밴드</button><button type=\"button\" data-scan=\"cross\">③ 10/20 교차·거래량</button><button type=\"button\" data-scan=\"breakout\">④ 전고점 돌파</button></div><div id=\"scanStatus\" class=\"tiny\" role=\"status\" aria-live=\"polite\">버튼을 눌러 검색하세요. 완료된 일봉만 사용합니다.</div><div id=\"scanResults\"></div></details><strong>LEADER 40</strong><input id=\"search\" class=\"search\" placeholder=\"종목 검색\" aria-label=\"종목 검색\"><div id=\"stockList\"></div></aside><main class=\"workspace\"><section class=\"chart\" aria-label=\"차트\"><div class=\"toolbar\"><label for=\"ticker\" class=\"tiny\">종목</label><select id=\"ticker\" aria-label=\"종목 선택\"></select><select id=\"mode\" aria-label=\"수업 방식\"><option value=\"learn\">기준 배우기</option><option value=\"chart\">차트로 연습하기</option></select><select id=\"language\" aria-label=\"AI 답변 언어\"><option value=\"auto\">Auto 언어</option><option value=\"ko\">한국어</option><option value=\"en\">English</option></select><select id=\"tf\" aria-label=\"차트 주기\"><option value=\"1d\">일봉</option><option value=\"30m\" selected>30분봉 · 스윙</option><option value=\"15m\">15분봉</option><option value=\"5m\">5분봉 · 단타</option></select><details class=\"sora-courses\" style=\"position:relative;display:inline-block;flex:none\"><summary style=\"cursor:pointer;font-weight:700;font-size:12px;padding:6px 9px;border:1px solid #c9d4e0;border-radius:7px;background:#f1faf6;white-space:nowrap\">가상대회 · 교육과정 ▾</summary><div style=\"position:absolute;z-index:30;top:100%;left:0;width:min(350px,85vw);padding:10px;background:#fff;border:1px solid #c9d4e0;border-radius:9px;box-shadow:0 8px 22px #1d354326\"><div class=\"tiny\">배운 전략으로 직접 종목을 찾고 실력을 검증하세요. · 가상 투자금 $100,000 (모의매매 개발 중)</div><div style=\"display:grid;grid-template-columns:repeat(3,minmax(0,1fr));gap:5px;margin-top:7px\"><button type=\"button\" id=\"startVolume\">볼륨 트레이딩</button><button type=\"button\" id=\"startTrend\">추세추종</button><button type=\"button\" id=\"startMinervini\">미너비니 SEPA/VCP</button></div><button type=\"button\" id=\"startContest\" style=\"width:100%;margin-top:6px;background:#f4f1ff\">가상대회 참가하기 · $100,000</button></div></details><nav class=\"index-links\" aria-label=\"시장 지수\"><span class=\"index-caption\">지수확인 :</span><button type=\"button\" data-index=\"QQQ\" aria-pressed=\"false\">QQQ</button><button type=\"button\" data-index=\"SPY\" aria-pressed=\"false\">SPY</button><button type=\"button\" data-index=\"IWM\" aria-pressed=\"false\">IWM</button></nav></div><div class=\"tiny\" id=\"chartStatus\">차트 조회 전</div><div id=\"wallNumbers\" class=\"tiny\" aria-live=\"polite\" style=\"display:flex;gap:16px;flex-wrap:wrap;padding:3px 5px;font-weight:700\"><span style=\"color:#b63c3c\">Call Wall: 확인 불가</span><span style=\"color:#087f60\">Put Wall: 확인 불가</span></div><div class=\"tv-wrap\" id=\"tvWrap\" aria-label=\"TradingView 주식 차트\"><div id=\"tvChart\" class=\"tradingview-widget-container\"></div></div><div class=\"tiny\"><span class=\"tv-credit\">TradingView 무료 차트 · 시세 지연 가능 · Wall은 별도 API 필요 · <a href=\"https://www.tradingview.com/\" target=\"_blank\" rel=\"noopener noreferrer\">TradingView</a></span></div></section><section class=\"chat\" aria-label=\"소라 대화\"><div class=\"messages\" id=\"messages\" role=\"log\" aria-live=\"polite\"></div><form id=\"chatForm\" class=\"entry\"><input id=\"question\" maxlength=\"1200\" placeholder=\"소라에게 차트 분석 질문...\" autocomplete=\"off\" aria-label=\"질문\"><button id=\"send\" type=\"submit\">전송</button></form></section></main></div></div><script>\n\"use strict\";\nconst GROUPS={\"A+\":[\"NVDA\",\"MSFT\",\"GOOGL\",\"AMZN\",\"META\",\"TSLA\",\"PLTR\",\"AVGO\",\"GEV\",\"TSM\"],\"A\":[\"MU\",\"CRDO\",\"ANET\",\"VRT\",\"ETN\",\"FIX\",\"APP\",\"LITE\",\"DELL\",\"NFLX\"],\"B\":[\"SNDK\",\"STX\",\"WDC\",\"INTC\",\"MXL\",\"MRVL\",\"COHR\",\"VIAV\",\"CIEN\",\"TER\"],\"C\":[\"IREN\",\"NBIS\",\"CIFR\",\"CLSK\",\"RKLB\",\"OKLO\",\"SMR\",\"RGTI\",\"QBTS\",\"SOUN\"]};\nconst $=id=>document.getElementById(id);const dailyMoves=new Map();const conversations=new Map();let indexChart=null;let chosen=\"AMZN\",pending=false,chartSeq=0,requestVersion=0,chatController=null;const chatKey=()=>($(\"mode\").value||\"learn\")+\":\"+chosen+\":\"+($(\"tf\").value||\"30m\");\nfunction add(role,text){const div=document.createElement(\"div\");div.className=\"bubble\"+(role===\"user\"?\" user\":\"\");div.textContent=(role===\"user\"?\"나: \":\"소라: \")+text;$(\"messages\").append(div);$(\"messages\").scrollTop=$(\"messages\").scrollHeight}\nfunction paintChat(){const items=conversations.get(chatKey())||[];if(!items.length&&$(\"mode\").value===\"learn\"){$(\"messages\").replaceChildren();add(\"assistant\",\"가상 사례로 한 문제씩 배우는 수업입니다. 수업 시작을 입력해 주세요. 실제 시장 분석은 아닙니다.\");return;}$(\"messages\").replaceChildren();if(!items.length)add(\"assistant\",chosen+\" 분석 준비됐습니다. 먼저 일봉 기울기와 위치를 확인하고, 30분봉 진입 구조 또는 5분봉 CORE 헤지 분석을 설명하겠습니다. 현재 데이터 연결 전에는 실시간 가격을 단정하지 않습니다.\");else items.forEach(x=>add(x.role,x.content))}\nfunction renderStockList(){const root=$(\"stockList\");root.replaceChildren();const q=$(\"search\").value.trim().toUpperCase();for(const [grade,names] of Object.entries(GROUPS)){for(const name of names.filter(s=>s.includes(q))){const b=document.createElement(\"button\");b.textContent=grade+\" · \"+name;const info=dailyMoves.get(name);b.dataset.trend=info?info.trend:\"unknown\";const sub=document.createElement(\"span\");sub.className=\"daily-move\";sub.textContent=info?info.text:\"최근 일봉 · 미확인\";b.append(sub);b.setAttribute(\"aria-pressed\",String(name===chosen));b.addEventListener(\"click\",()=>choose(name));root.append(b)}}}\nfunction choose(ticker){cancelChat();indexChart=null;updateIndexButtons();chosen=ticker;$(\"ticker\").value=ticker;renderStockList();paintChat();updateChart()}\nconst all=Object.entries(GROUPS).flatMap(([grade,names])=>names.map(symbol=>({grade,symbol})));for(const x of all){const opt=document.createElement(\"option\");opt.value=x.symbol;opt.textContent=x.symbol+\" · \"+x.grade;$(\"ticker\").append(opt)}\n\n// Previous two reported daily closes, not a real-time quote. Missing data stays neutral.\nasync function checkDailyMove(ticker){try{const res=await fetch(\"/api/search?mode=daily_bars&ticker=\"+encodeURIComponent(ticker),{credentials:\"same-origin\",cache:\"no-store\"});if(!res.ok)throw Error(\"HTTP \"+res.status);const j=await res.json();const bars=Array.isArray(j.bars)?j.bars.filter(x=>Number.isFinite(Number(x.close))&&Number(x.close)>0&&/^\\\\d{4}-\\\\d{2}-\\\\d{2}$/.test(x.time||\"\")):[];if(bars.length<2)throw Error(\"missing bars\");const prev=bars[bars.length-2],last=bars[bars.length-1];const age=(Date.now()-Date.parse(last.time+\"T00:00:00Z\"))/86400000;if(age< -1||age>7)throw Error(\"stale data\");const pct=(Number(last.close)/Number(prev.close)-1)*100;if(!Number.isFinite(pct))throw Error(\"invalid change\");const trend=Math.abs(pct)<0.005?\"flat\":pct>0?\"up\":\"down\";dailyMoves.set(ticker,{trend,text:\"최근 일봉 \"+last.time+\" · \"+(pct>0?\"▲ +\":pct<0?\"▼ \":\"— \")+pct.toFixed(2)+\"%\"});}catch(err){dailyMoves.set(ticker,{trend:\"unknown\",text:\"최근 일봉 · 미확인\"});}renderStockList()}\nasync function loadDailyMoves(){const universe=all.map(x=>x.symbol);let pos=0;const worker=async()=>{while(pos<universe.length){const ticker=universe[pos++];await checkDailyMove(ticker)}};await Promise.all([worker(),worker()])}\nfunction trace(bars){const svg=$(\"plot\");svg.replaceChildren();const last=bars.slice(-55);if(last.length<2)throw Error(\"가격 데이터 부족\");const ys=last.map(x=>Number(x.close));if(ys.some(x=>!Number.isFinite(x)))throw Error(\"가격 데이터 오류\");const lo=Math.min(...ys),hi=Math.max(...ys),span=hi-lo||1;const pts=ys.map((v,i)=>[8+(i/(ys.length-1))*304,100-(v-lo)/span*85]);const poly=document.createElementNS(\"http://www.w3.org/2000/svg\",\"polyline\");poly.setAttribute(\"points\",pts.map(v=>v.join(\",\")).join(\" \"));poly.setAttribute(\"fill\",\"none\");poly.setAttribute(\"stroke\",\"#5be0ad\");poly.setAttribute(\"stroke-width\",\"2\");svg.append(poly)}\nfunction updateIndexButtons(){document.querySelectorAll(\"[data-index]\").forEach(b=>b.setAttribute(\"aria-pressed\",String(indexChart===b.dataset.index)))}\ndocument.querySelectorAll(\"[data-index]\").forEach(b=>b.addEventListener(\"click\",()=>{\n indexChart=b.dataset.index;updateIndexButtons();updateChart();\n}));\n\nlet lwScriptPromise=null;\nfunction loadLightweight(){\n if(window.LightweightCharts)return Promise.resolve();\n if(lwScriptPromise)return lwScriptPromise;\n lwScriptPromise=new Promise((resolve,reject)=>{\n  const script=document.createElement(\"script\");\n  script.src=\"https://unpkg.com/lightweight-charts@4.2.3/dist/lightweight-charts.standalone.production.js\";\n  script.onload=()=>window.LightweightCharts?resolve():reject(Error(\"CHART_LIBRARY_UNAVAILABLE\"));\n  script.onerror=()=>reject(Error(\"CHART_LIBRARY_NETWORK\"));\n  document.head.append(script);\n }).catch(error=>{lwScriptPromise=null;throw error});\n return lwScriptPromise;\n}\nlet lwCharts=[];\nfunction destroyLightweight(){\n lwCharts.forEach(x=>{try{x.remove()}catch{}});lwCharts=[];\n}\nasync function updateChart(){\n const ticker=indexChart||chosen, tf=indexChart?\"1d\":$(\"tf\").value, seq=++chartSeq;\n destroyLightweight();\n $(\"wallNumbers\").innerHTML=\"<span style=\\\"color:#b63c3c\\\">Call Wall: 확인 불가</span><span style=\\\"color:#087f60\\\">Put Wall: 확인 불가</span>\";\n const root=$(\"tvChart\");root.replaceChildren();\n const notice=document.createElement(\"div\");notice.textContent=\"검증된 봉 데이터와 거래량을 불러오는 중…\";\n notice.style.cssText=\"padding:15px;color:#526179;font-size:13px\";root.append(notice);\n $(\"chartStatus\").textContent=ticker+\" · \"+tf+\" · 지연 OHLCV 조회 중\";\n try{\n  const response=await fetch(\"/api/swing_radar_chart?ticker=\"+encodeURIComponent(ticker)+\"&tf=\"+encodeURIComponent(tf)+\"&walls=1\",{credentials:\"same-origin\"});\n  if(!response.ok)throw Error(\"시세 API HTTP \"+response.status);\n  const json=await response.json();\n  if(seq!==chartSeq)return;\n  if(!Array.isArray(json.bars)||json.bars.length<5||json.bars.some(b=>b.complete===false||b.coverage_ok===false))throw Error(\"검증된 완료봉 데이터 부족\");\n  await loadLightweight();\n  if(seq!==chartSeq)return;\n  const bars=json.bars.map(b=>({time:Math.floor(Number(b.t)/1000),open:Number(b.open),high:Number(b.high),low:Number(b.low),close:Number(b.close),volume:Number(b.volume),evp:Number(b.evp)}))\n   .filter(b=>Number.isFinite(b.time)&&[b.open,b.high,b.low,b.close,b.volume,b.evp].every(Number.isFinite))\n   .sort((a,b)=>a.time-b.time).filter((b,i,arr)=>i===0||b.time!==arr[i-1].time);\n  if(bars.length<5)throw Error(\"차트 표시 가능한 봉 부족\");\n  root.replaceChildren();\n  const candleHost=document.createElement(\"div\");candleHost.style.cssText=\"height:72%;min-height:210px\";\n  const smoothHost=document.createElement(\"div\");smoothHost.style.cssText=\"height:27%;min-height:90px;border-top:1px solid #dce5ed\";\n  root.style.cssText=\"height:100%;min-height:360px;width:100%\";\n  root.append(candleHost,smoothHost);\n  const L=window.LightweightCharts;\n  const base={layout:{background:{color:\"#ffffff\"},textColor:\"#253347\"},grid:{vertLines:{color:\"#f2f5f8\"},horzLines:{color:\"#edf1f5\"}},timeScale:{timeVisible:tf!==\"1d\",secondsVisible:false},rightPriceScale:{borderVisible:false}};\n  const main=L.createChart(candleHost,{...base,width:candleHost.clientWidth,height:candleHost.clientHeight});\n  const candles=main.addCandlestickSeries({upColor:\"#16a076\",downColor:\"#d95555\",wickUpColor:\"#16a076\",wickDownColor:\"#d95555\",borderVisible:false});\n  candles.setData(bars.map(({time,open,high,low,close})=>({time,open,high,low,close})));\n  const volumes=main.addHistogramSeries({priceFormat:{type:\"volume\"},priceScaleId:\"vol\",lastValueVisible:false,priceLineVisible:false});\n  main.priceScale(\"vol\").applyOptions({scaleMargins:{top:.78,bottom:0}});\n  candles.priceScale().applyOptions({scaleMargins:{top:.08,bottom:.25}});\n  volumes.setData(bars.map(b=>({time:b.time,value:b.volume,color:b.close>=b.open?\"#16a07680\":\"#d9555580\"})));\n  const wall=json.wall||{};\n  const validWall=(v)=>v!==null&&v!==undefined&&String(v).trim()!==\"\"&&Number.isFinite(Number(v))&&Number(v)>0;\n  const wallPrice=(v)=>validWall(v)?\"$\"+Number(v).toLocaleString(\"en-US\",{minimumFractionDigits:2,maximumFractionDigits:2}):\"확인 불가\";\n  $(\"wallNumbers\").textContent=\"Call Wall: \"+wallPrice(wall.call_wall)+\"   |   Put Wall: \"+wallPrice(wall.put_wall);\n  // Educational mode: show verified Wall prices as numbers only. Students mark levels themselves.\n  const lower=L.createChart(smoothHost,{...base,width:smoothHost.clientWidth,height:smoothHost.clientHeight,handleScroll:false});\n  const evp=lower.addLineSeries({color:\"#366ab9\",lineWidth:2,title:\"EVP (추정 · TOS Smooth 아님)\",priceFormat:{type:\"price\",precision:2,minMove:.01}});\n  evp.setData(bars.map(b=>({time:b.time,value:b.evp})));\n  evp.createPriceLine({price:0,color:\"#a5afb9\",lineWidth:1,lineStyle:2,axisLabelVisible:false});\n  main.timeScale().fitContent();lower.timeScale().fitContent();\n  lwCharts=[main,lower];\n  if(typeof ResizeObserver!==\"undefined\"){\n   const observer=new ResizeObserver(()=>{if(seq!==chartSeq){observer.disconnect();return;}try{main.applyOptions({width:candleHost.clientWidth,height:candleHost.clientHeight});lower.applyOptions({width:smoothHost.clientWidth,height:smoothHost.clientHeight})}catch{}});\n   observer.observe(root);\n  }\n  $(\"chartStatus\").textContent=ticker+\" · \"+tf+\" · Massive 지연 완료봉 | 거래량: 실제 OHLCV | Smooth 대체: EVP 추정치(원본 아님)\"+(Number.isFinite(Number(wall.call_wall))&&Number.isFinite(Number(wall.put_wall))?\" | Wall 참고선\":\" | Wall 데이터 미확인\");\n }catch(error){\n  if(seq!==chartSeq)return;\n  destroyLightweight();updateChartLegacy();\n  $(\"chartStatus\").textContent=ticker+\" · \"+tf+\" · 커스텀 지표 데이터 확인 불가 (\"+String(error.message||error)+\"). TradingView 기본 차트 표시.\";\n }\n}\nfunction updateChartLegacy(){const ticker=indexChart||chosen,tf=indexChart?\"1d\":$(\"tf\").value,seq=++chartSeq;const exchange=([\"TSM\",\"GEV\",\"ETN\",\"FIX\",\"APP\",\"DELL\",\"SNDK\",\"STX\",\"WDC\",\"CIEN\",\"VRT\",\"LITE\",\"RGTI\",\"QBTS\"].includes(ticker)?\"NYSE\":\"NASDAQ\");const symbol=indexChart?({QQQ:\"NASDAQ:QQQ\",SPY:\"AMEX:SPY\",IWM:\"AMEX:IWM\"})[ticker]:exchange+\":\"+ticker;const interval=({\"1d\":\"D\",\"30m\":\"30\",\"15m\":\"15\",\"5m\":\"5\"})[tf]||\"D\";$(\"chartStatus\").textContent=ticker+\" · \"+tf+\" · TradingView 차트 (지수 버튼은 차트 보기 전용 · 시세 지연 가능)\";const root=$(\"tvChart\");root.replaceChildren();const host=document.createElement(\"div\");host.className=\"tradingview-widget-container__widget\";root.append(host);const script=document.createElement(\"script\");script.type=\"text/javascript\";script.async=true;script.src=\"https://s3.tradingview.com/external-embedding/embed-widget-advanced-chart.js\";script.textContent=JSON.stringify({autosize:true,symbol: symbol,interval:interval,timezone:\"America/New_York\",theme:\"light\",style:\"1\",locale:\"kr\",allow_symbol_change:false,hide_top_toolbar:false,hide_legend:false,save_image:false,calendar:false,support_host:\"https://www.tradingview.com\"});script.onerror=()=>{if(seq===chartSeq)$(\"chartStatus\").textContent=ticker+\" · TradingView 로딩 실패 (연결 또는 브라우저 차단 확인)\"};root.append(script)}\n\n// Scanner v1 uses existing protected, delayed daily OHLCV endpoint. No Hull21 band or TOS Smooth inference.\nconst scanSymbols=Object.values(GROUPS).flat();\nconst scanCache=new Map();let scanSeq=0;\nfunction sma(rows,n,i){if(i<n-1)return null;let v=0;for(let j=i-n+1;j<=i;j++)v+=Number(rows[j].close);return v/n}\nfunction scanEval(kind,rows){\n if(rows.length<65)return {status:\"unknown\",reason:\"완료 일봉 65개 미만\"};\n const i=rows.length-1,c=Number(rows[i].close),p=Number(rows[i-1].close),v=Number(rows[i].volume);\n const avgVol=rows.slice(i-20,i).reduce((t,b)=>t+Number(b.volume),0)/20;\n const a21=sma(rows,21,i),a50=sma(rows,50,i),a50old=sma(rows,50,i-5);\n if(![c,p,v,avgVol,a21,a50,a50old].every(Number.isFinite)||avgVol<=0)return {status:\"unknown\",reason:\"데이터 오류\"};\n if(kind===\"hull\")return {status:\"unknown\",reason:\"Hull21 밴드·원본 Smooth 미연결\"};\n if(kind===\"pullback\"){\n  // Explicit screening convention, not an entry signal: within ±2% SMA21, rising SMA50, price above SMA50.\n  const ok=c>a50&&a50>a50old&&Math.abs(c/a21-1)<=0.02;\n  return {status:ok?\"watch\":\"no\",reason:ok?\"SMA21 ±2% · SMA50 상승 (관찰 후보)\":\"조건 미충족\"};\n }\n if(kind===\"cross\"){\n  // Experimental SMA10/20 crossover; approved volume explosion threshold is not yet available.\n  const cross=sma(rows,10,i)>sma(rows,20,i)&&sma(rows,10,i-1)<=sma(rows,20,i-1);\n  return {status:\"unknown\",reason:cross?\"10/20 SMA 상향 교차 관찰 · 거래량 폭발 기준 미확정\":\"교차 없음 · 거래량 기준 미확정\"};\n }\n if(kind===\"breakout\"){\n  const hi=Math.max(...rows.slice(i-20,i).map(b=>Number(b.high)));\n  // Explicit preliminary 20-session, close confirmation and volume > 20-day avg.\n  const ok=c>hi&&v>avgVol;\n  return {status:ok?\"watch\":\"no\",reason:ok?\"직전 20거래일 고점 종가 돌파 · 거래량 평균 초과 (관찰 후보)\":\"조건 미충족\"};\n }\n return {status:\"unknown\",reason:\"규칙 없음\"};\n}\nasync function scanDaily(symbol){\n if(scanCache.has(symbol))return scanCache.get(symbol);\n const r=await fetch(\"/api/swing_radar_chart?ticker=\"+encodeURIComponent(symbol)+\"&tf=1d\",{credentials:\"same-origin\"});\n if(!r.ok){let errorCode=\"HTTP_\"+r.status;try{const err=await r.json();errorCode=String(err.error_code||errorCode)}catch{}throw Error(errorCode)}\n const j=await r.json();if(j.tf!==\"1d\"||!Array.isArray(j.bars)||!j.bars.length)throw Error(\"데이터 미확인\");\n if(j.bars.some(b=>b.complete===false||b.coverage_ok===false))throw Error(\"미완료 봉 또는 데이터 누락\");\n scanCache.set(symbol,j.bars);return j.bars;\n}\nasync function runScan(kind){\n const seq=++scanSeq,root=$(\"scanResults\");root.replaceChildren();\n document.querySelectorAll(\"[data-scan]\").forEach(b=>b.disabled=true);\n const names={pullback:\"SMA21 눌림\",hull:\"Hull21 밴드\",cross:\"10/20 교차\",breakout:\"전고점 돌파\"};\n if(kind===\"hull\"){$(\"scanStatus\").textContent=\"② Hull21 밴드: 원본 밴드·Smooth 데이터 없음 — 결과 산출 불가\";document.querySelectorAll(\"[data-scan]\").forEach(b=>b.disabled=false);return}\n $(\"scanStatus\").textContent=names[kind]+\" · 40종목 일봉 조회 중 (15분 이상 지연 가능)\";\n let pos=0,checked=0,unknown=0,found=0;const errors=new Map();\n const worker=async()=>{while(pos<scanSymbols.length&&seq===scanSeq){\n  const symbol=scanSymbols[pos++];let res;\n  try{res=scanEval(kind,await scanDaily(symbol))}catch(e){const code=String(e.message||\"DATA_UNAVAILABLE\");errors.set(code,(errors.get(code)||0)+1);res={status:\"unknown\",reason:code}}\n  checked++;if(res.status===\"unknown\")unknown++;\n  if(res.status===\"watch\"){found++;const b=document.createElement(\"button\");b.type=\"button\";b.textContent=symbol+\" · \"+res.reason;b.addEventListener(\"click\",()=>choose(symbol));root.append(b)}\n  if(kind===\"cross\"&&res.reason.startsWith(\"10/20\")){const b=document.createElement(\"button\");b.type=\"button\";b.textContent=symbol+\" · \"+res.reason;b.addEventListener(\"click\",()=>choose(symbol));root.append(b)}\n  $(\"scanStatus\").textContent=names[kind]+\" · \"+checked+\"/40 조회 · 관찰 \"+found+\" · 미확인 \"+unknown;\n }};\n await Promise.all([worker(),worker(),worker()]);\n if(seq===scanSeq){if(!root.children.length){const p=document.createElement(\"p\");p.className=\"tiny\";p.textContent=\"표시할 관찰 후보 없음 (미확인 \"+unknown+\"개는 제외)\";root.append(p)}\n $(\"scanStatus\").textContent+=\" · 스캔 완료 · 연구용, 매매 신호 아님\";\n if(errors.size){const codes=[...errors].sort((a,b)=>b[1]-a[1]).map(([code,count])=>code+\" \"+count+\"개\");const diag=document.createElement(\"p\");diag.className=\"tiny\";diag.textContent=\"데이터 실패 원인: \"+codes.join(\" / \")+\" (인증·공급자·지연 여부 추가 확인 필요)\";root.append(diag)}\n if(unknown===40)$(\"scanStatus\").textContent+=\" · 40개 모두 미확인: 스캔 조건 불충족으로 해석 금지\";\n document.querySelectorAll(\"[data-scan]\").forEach(b=>b.disabled=false)}\n}\ndocument.querySelectorAll(\"[data-scan]\").forEach(b=>b.addEventListener(\"click\",()=>runScan(b.dataset.scan)));\nfunction cancelChat(){requestVersion++;if(chatController){chatController.abort();chatController=null;}pending=false;$(\"send\").disabled=false;}\nfunction startPatternPractice(title, principles, prompt){\n $(\"mode\").value=\"chart\";\n $(\"tf\").value=\"1d\";\n cancelChat(); indexChart=null; updateIndexButtons(); updateChart(); paintChat();\n add(\"assistant\",title+\"\\\\n\"+principles+\"\\\\n\\\\n직접 종목과 패턴을 찾아 차트에서 확인하세요. 패턴의 위치, 거래량, 추세를 질문하면 소라가 해당 원리만 설명합니다. 소라는 TradingView 차트를 직접 읽지 못하며 관찰값을 추측하지 않습니다.\");\n $(\"question\").value=\"\";\n $(\"question\").placeholder=prompt;\n $(\"question\").focus();\n const panel=document.querySelector(\".sora-courses\"); if(panel)panel.open=false;\n}\nfunction startVolumeCourse(){\n startPatternPractice(\"볼륨 트레이딩 · 패턴 찾기\",\n \"원리: ① 시장과 주도주 확인 ② 일봉 눌림목·거래량 변화 찾기 ③ 30분봉에서 매도세 둔화·매수세 증가·Smooth 전환 확인 ④ 5분봉 기준봉 돌파와 손절 조건 확인. 매도세 감소만으로 매수세 증가를 단정하지 않습니다.\",\n \"예: NVDA 일봉에서 거래량이 줄어든 눌림목을 찾았는데...\");\n}\nfunction startTrendCourse(){\n startPatternPractice(\"추세추종 · 패턴 찾기\",\n \"원리: 시장과 주도주를 살핀 뒤 주봉 Stage 1~4 및 일봉 20·50일선, 거래량을 확인하고 상승 추세의 눌림목 또는 Stage 1→2 전환 패턴을 찾습니다.\",\n \"예: 일봉 20일선 회복이 Stage 2 전환일까요?\");\n}\nfunction startMinerviniCourse(){\n startPatternPractice(\"미너비니 SEPA/VCP · 패턴 찾기\",\n \"원리: Stage 2 상승 추세와 50·150·200일 이동평균선, 상대강도, 변동폭·거래량이 수축하는 VCP 패턴, 피벗 돌파를 확인합니다.\",\n \"예: 이 종목의 거래량 수축이 VCP 패턴인가요?\");\n}\ndocument.getElementById(\"startTrend\").addEventListener(\"click\",startTrendCourse);\ndocument.getElementById(\"startMinervini\").addEventListener(\"click\",startMinerviniCourse);\nfunction startContestPreview(){\n add(\"assistant\",\"가상대회 · 시작 자금 $100,000 (개발 중)\\n현재는 참가 및 모의 주문 기록 기능이 아직 연결되지 않았어요. 실제 가상 계좌·성적표가 생성된 것은 아닙니다. 향후 종목 선택 → 가상 주문 → 매매일지 → 성적표 순서로 연습하게 됩니다. 먼저 볼륨 발자국 과정을 시작해 주세요.\");\n}\ndocument.getElementById(\"startVolume\").addEventListener(\"click\",startVolumeCourse);\ndocument.getElementById(\"startContest\").addEventListener(\"click\",startContestPreview);\nasync function submit(e){\n e.preventDefault();\n if(pending)return;\n const question=$(\"question\").value.trim();\n if(!question)return;\n const ticker=chosen,tf=$(\"tf\").value,key=chatKey(),version=++requestVersion;\n const history=(conversations.get(key)||[]).slice(-8);\n const full=conversations.get(key)||[];\n full.push({role:\"user\",content:question});\n conversations.set(key,full);\n add(\"user\",question);\n $(\"question\").value=\"\";\n pending=true;$(\"send\").disabled=true;\n chatController=new AbortController();\n const controller=chatController;\n try{\n   const r=await fetch(\"/api/sora_chat\",{method:\"POST\",credentials:\"same-origin\",\n    headers:{\"Content-Type\":\"application/json\"},\n    body:JSON.stringify({ticker,tf,mode:$(\"mode\").value,language:$(\"language\").value,message:question,history}),signal:controller.signal});\n   let j;\n   try{j=await r.json();}catch{throw Error(\"AI 서버 응답을 읽지 못했습니다. HTTP \"+r.status);}\n   if(version!==requestVersion || key!==chatKey())return;\n   if(!r.ok)throw Error((j.kind?\"[\"+j.kind+\"] \":\"\")+(j.error||\"응답 실패\"));\n   if(j.ticker!==ticker||j.tf!==tf)throw Error(\"AI 응답 종목/시간봉 불일치\");\n   const answer=String(j.answer||\"\").trim();\n   if(!answer)throw Error(\"빈 응답\");\n   const meta=j.market||{};\n   const source=j.lesson||{};const criteria=j.core_criteria||{};\n   const suffix=$(\"mode\").value===\"learn\"?\"\":(\"\\n\\n[분석 기준] \"+ticker+\" · \"+tf+\" · 마지막 완료봉 시작 \"+(meta.last_bar_utc||\"미확인\")+\" · \"+(meta.data_status||\"미확인\")+\"\\n[참고 자료] \"+(source.title||\"미확인\")+\" / \"+(source.version||\"버전 없음\")+\"\\n[메인 교육기준] \"+(criteria.title||\"미연결\")+\" \"+(criteria.version||\"\"));\n   full.push({role:\"assistant\",content:answer+suffix});\n   add(\"assistant\",answer+suffix);\n }catch(err){\n   if(err.name===\"AbortError\")return;\n   if(version===requestVersion&&key===chatKey())add(\"assistant\",\"연결 오류: \"+err.message);\n }finally{\n   if(version===requestVersion){pending=false;$(\"send\").disabled=false;chatController=null;}\n }\n}\n\n$(\"ticker\").addEventListener(\"change\",e=>choose(e.target.value));$(\"tf\").addEventListener(\"change\",()=>{cancelChat();indexChart=null;updateIndexButtons();paintChat();updateChart()});$(\"language\").addEventListener(\"change\",()=>{cancelChat();paintChat()});$(\"mode\").addEventListener(\"change\",()=>{cancelChat();paintChat();$(\"question\").placeholder=$(\"mode\").value===\"learn\"?\"수업 시작 또는 문제 답변...\":\"차트 분석 질문...\";});$(\"search\").addEventListener(\"input\",renderStockList);$(\"chatForm\").addEventListener(\"submit\",submit);$(\"ticker\").value=chosen;renderStockList();paintChat();updateChart();loadDailyMoves();\n</script></body></html>"
class handler(BaseHTTPRequestHandler):
 def do_GET(self):
  if not require_access(self):return
  body=HTML.encode("utf-8")
  self.send_response(200)
  self.send_header("Content-Type","text/html; charset=utf-8")
  self.send_header("Content-Length",str(len(body)))
